B.bFl=new A.r("O Ache Obra pode coletar informa\xe7\xf5es fornecidas diretamente pelo usu\xe1rio durante o cadastro, utiliza\xe7\xe3o e atualiza\xe7\xe3o do perfil, incluindo nome, e-mail, telefone/WhatsApp, CPF quando necess\xe1rio, cidade, estado, categoria e perfil de uso, como Cliente, Profissional, Arquiteto ou Engenheiro.",null,B.cR,null,null,null,null,null,null,null,null)
B.af=new A.bh(null,10,null,null)
B.bz_=new A.r("Tamb\xe9m poder\xe3o ser armazenadas informa\xe7\xf5es inseridas voluntariamente pelo usu\xe1rio em seu perfil ou durante a utiliza\xe7\xe3o dos recursos disponibilizados pelo aplicativo, incluindo informa\xe7\xf5es profissionais, descri\xe7\xf5es, solicita\xe7\xf5es, publica\xe7\xf5es, imagens e outros conte\xfados necess\xe1rios ao funcionamento da plataforma.",null,B.cR,null,null,null,null,null,null,null,null)
B.bBl=new A.r("Podemos ainda coletar informa\xe7\xf5es t\xe9cnicas necess\xe1rias ao funcionamento e \xe0 seguran\xe7a do servi\xe7o, como identificadores da conta, informa\xe7\xf5es de autentica\xe7\xe3o, identificadores do dispositivo, tokens utilizados para notifica\xe7\xf5es e registros t\xe9cnicos relacionados ao funcionamento do aplicativo.",null,B.cR,null,null,null,null,null,null,null,null)
B.bx_=new A.r("2. Uso das Informa\xe7\xf5es",null,B.cn,null,null,null,null,null,null,null,null)
